"""Deutschsprachiger AW157-Aggregatbericht und Abgabe, keine Einzelwerte."""
import math
from collections import Counter
import numpy as np
import pandas as pd

def interval(values,total):
    v=np.array([x for x in values if x is not None and np.isfinite(x)],float)
    return np.quantile(v,[.025,.975]).tolist() if len(v)>=math.ceil(.95*total) else [None,None]
def fmt(v,d=3):return 'nicht schätzbar' if v is None else f'{v:.{d}f}'
def ci(v):return '['+fmt(v[0])+'; '+fmt(v[1])+']'
def exp(v):return None if v is None or v>700 else float(np.exp(v))
def table(headers,rows):
    return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+''.join('| '+' | '.join(map(str,r))+' |\n' for r in rows)+'\n'

def report(a):
    a.verify()
    a.bind(__file__);a.bind(a.ROOT/'werkzeuge/b_test/aw157_verify.py')
    out=a.OUT;root=a.ROOT;e,p=a.outcome_data();population=a.json.loads(a.bind(out/'population.json').read_text())
    stable_sources={}
