        delta=c['point'].get('r12',0)-c['point'].get('r21',0);dci=interval([b['r12']-b['r21'] for b in c['boot']],1000)
        summary['direction_difference']=delta;summary['direction_difference_ci']=dci
        rows.append({'section':'latent','fold':c['group'] if c['group'] in ['train','validation'] else 'train+validation','group':c['group'],'basis':c['mode'],'source':'A_original_pairs','method':'r12_minus_r21','estimate':delta,'ci_low':dci[0],'ci_high':dci[1],'bootstrap_valid':len(c['boot']),'bootstrap_total':1000,'n_pairs':c['n_pairs'],'n_subjects':c['n_subjects'],'input_file':input_source+' + '+str(a.REPEAT)+' + '+str(a.PAIR),'row_key':c['group']+'/'+c['mode']+'/r12_minus_r21','script':'werkzeuge/b_test/aw157_run.py:correlations'})
        if summary['latent'] is None or summary['latent_ci'][0] is None:verdict='Gate offen'
        elif abs(summary['latent'])>1:verdict='Modellwarnung: außerhalb [-1;1]'
