    rows.append({'section':'orientation','fold':'validation','group':'AW025_rotationsvergleich','source':'AW025','method':'original','estimate':rotated['original_auc_paired'],'n_subjects':rotated['validation_pairs'],'cases':rotated['validation_positive'],'input_file':str(path025),'input_sha256':a.sha(path025),'row_key':'results/variant=VB-VF01-07/original_auc_paired','script':'werkzeuge/varianten/aw025_auswerten.py; AW157 nur Übernahme'})
    rows.append({'section':'orientation','fold':'validation','group':'AW025_rotationsvergleich','source':'AW025','method':'shape','estimate':rotated['variant_auc_paired'],'delta_auc':rotated['delta_auc'],'delta_auc_ci_low':rotated['uncorrected_ci_95'][0],'delta_auc_ci_high':rotated['uncorrected_ci_95'][1],'n_subjects':rotated['validation_pairs'],'cases':rotated['validation_positive'],'input_file':str(path025),'input_sha256':a.sha(path025),'row_key':'results/variant=VB-VF01-07','script':'werkzeuge/varianten/aw025_auswerten.py; AW157 nur Übernahme'})
    for r in rows:
        r['run']='A155-2026-10-04-d6e70e';r['seed']=a.SEED
        if r['section']=='outcome':
            r['error_input_files']=(str(root/'werkzeuge/b_test/aw157_protokoll.md')+'; '+str(root/'koordination/auftraege/AW-157.md')) if r['source'].startswith('icc_') else (input_source+'; '+str(a.REPEAT)+'; '+str(a.PAIR))
    csv=root/'nachrechnung/b_konstrukt.csv';pd.DataFrame(rows).to_csv(csv,index=False,encoding='utf-8-sig')
